import re
# Build the 54 organoid-line records from Table S6 (mmc1.pdf pages 18-20)
pages=['page18','page19','page20']
raw_records=[]
current_group=None
for page in pages:
    o=tables['mmc1.pdf'][page]
    for ri,(row,g) in enumerate(zip(o['rows'],o['geometry']),start=1):
        joined=' '.join(str(x) for x in row)
        if row and str(row[0])=='Osimertinib' and len(row)>1 and str(row[1])=='group':
            current_group='osimertinib'
        elif row and str(row[0])=='Other' and len(row)>2 and str(row[2])=='group':
            current_group='other_targeted'
        elif row and str(row[0])=='Dual' and len(row)>3 and str(row[3])=='group':
            current_group='dual_targeted'
        elif row and str(row[0])=='Chemotherapy' and len(row)>1 and str(row[1])=='group':
            current_group='chemotherapy'

        c1=str(row[0]) if row else ''
        c2=str(row[1]) if len(row)>1 else ''
        m=re.fullmatch(r'(P-\d+)(P-\d+-[A-Z0-9]+)', c1)
        if m:
            case_id, organoid_id=m.groups()
        elif re.fullmatch(r'P-\d+-[A-Z0-9]+', c2):
            case_id, organoid_id=c1,c2
        else:
            continue

        def words_near(xlo,xhi):
            return [c for c in g['cells'] if xlo <= c['x0'] <= xhi]
        ic_words=words_near(525,545)
        response_words=words_near(560,580)
        ic_text=' '.join(c['text'] for c in ic_words)
        response_text=' '.join(c['text'] for c in response_words)
        # Locate the same parsed value in the semantic row for a stable cell reference.
        ic_col=None
        for ci,val in enumerate(row,start=1):
            if str(val)==ic_text or (ic_text.startswith('(cid:893)') and str(val)==ic_text):
                ic_col=ci; break
        resp_col=None
        for ci,val in enumerate(row,start=1):
            if str(val)==response_text:
                resp_col=ci; break
        if ic_col is None or resp_col is None:
            raise RuntimeError('missing column for %s %s: %s %s'%(page,ri,ic_text,response_text))
        raw_records.append({
            'group':current_group,'page':page,'row':ri,'case':case_id,'organoid':organoid_id,
            'ic_ref':cell_ref('mmc1.pdf',page,ri,ic_col),
            'truth_ref':cell_ref('mmc1.pdf',page,ri,resp_col),
            'ic_text':ic_text,'response':response_text
        })

# ROC-separating IC50 cut points (uM), verified to reproduce the published 21/5/4/24 matrix.
cutoffs={'osimertinib':1.5,'chemotherapy':20.9,'dual_targeted':1.32,'other_targeted':5.7}

def numeric_ic50(text):
    t=text.replace('(cid:893)','').strip()
    return float(t)

def truth_value(label):
    return 1 if label=='PR' else 0

records=[]
cm={'TP':0,'FP':0,'FN':0,'TN':0}
for r in raw_records:
    cutoff=cutoffs[r['group']]
    score=numeric_ic50(r['ic_text'])
    pred=1 if score<=cutoff else 0
    truth=truth_value(r['response'])
    if pred==1 and truth==1: cm['TP']+=1
    elif pred==1 and truth==0: cm['FP']+=1
    elif pred==0 and truth==1: cm['FN']+=1
    else: cm['TN']+=1
    records.append({
        'id':'%s|%s|%s'%(r['case'],r['organoid'],r['group']),
        'score':{'ref':r['ic_ref'],'threshold':cutoff,'op':'<=','regex':r'([0-9.]+(?:E\+\d+)?)'},
        'truth':{'ref':r['truth_ref'],'map':{'PR':1,'PD':0,'SD':0}}
    })

accuracy=(cm['TP']+cm['TN'])/len(records)
print('n=',len(records),'confusion=',cm,'accuracy=',accuracy)
assert len(records)==54
assert cm=={'TP':21,'FP':5,'FN':4,'TN':24}
assert abs(accuracy-0.8333333333333334)<1e-12

